corrected_code:
package graph

import (
	"context"
	"errors"
	"myapp/auth"
	"myapp/graph/model"
)

func (r *QueryResolver) ProjectSourceRepository(ctx context.Context, repoID string) (*model.Repository, error) {
	userID := auth.GetUserID(ctx)
	hasAccess, err := r.RepoStore.UserHasAccess(ctx, repoID, userID)
	if err != nil || !hasAccess {
		return nil, errors.New("access denied: user does not have access to this repository")
	}

	repo, err := r.RepoStore.GetRepository(ctx, repoID)
	if err != nil {
		return nil, err
	}

	return repo, nil
}
